def max_subarray(xs):
    if not xs:
        raise ValueError("The input list cannot be empty")

    max_current = max_global = xs[0]
    for num in xs[1:]:
        max_current = max(num, max_current + num)
        if max_current > max_global:
            max_global = max_current

    return max_global
